+		{name: "fetch omitted snapshot", wants: 1},
+		{name: "use supplied empty snapshot", known: true},
+	} {
+		t.Run(test.name, func(t *testing.T) {
+			beforeSnapshots := fixture.fake.CallCount("session.snapshot")
