12: func projectHasActiveWorker(tasks []store.Task) bool {
13: 	for _, task := range tasks {
14: 		if task.State == store.StateSpawning || task.State == store.StateWorking || task.State == store.StateBlocked || task.State == store.StateStalled || task.AgentStatus == "working" {
15: 			return true
16: 		}
17: 	}
18: 	return false
19: }
20: 
21: func projectReadyToPark(project store.Project, tasks []store.Task, now time.Time, grace time.Duration) bool {
22: 	return !project.IsDown() && !project.IsParked() && project.LeadAbsentSince > 0 && !projectHasActiveWorker(tasks) && now.UnixMilli()-project.LeadAbsentSince >= grace.Milliseconds()
23: }
24: 
25: func parkProjectIfIdle(ctx context.Context, db *store.DB, project store.Project, now time.Time) (bool, error) {
26: 	tasks, err := db.LiveTasks(ctx, project.ID)
27: 	if err != nil {
28: 		return false, err
29: 	}
30: 	if !projectReadyToPark(project, tasks, now, projectParkGrace) {
31: 		return false, nil
32: 	}
33: 	return db.ParkProjectIfIdle(ctx, project, now, projectParkGrace)
34: }
35: 
36: func projectParkReason() string {
37: 	return "Lead is missing and no Worker is active; its Watch is paused. Run `posse up` in the Project folder to resume it."
38: }
